Java.Iterative:
public void insertionSort(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

Java.Functions:
public void insertionSort(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        insertIntoPrefix(arr, i);
    }
}

private void insertIntoPrefix(int[] arr, int index) {
    int key = arr[index];
    int j = index - 1;
    while (j >= 0 && arr[j] > key) {
        arr[j + 1] = arr[j];
        j--;
    }
    arr[j + 1] = key;
}

Java.Recursion:
public void insertionSortRecursive(int[] arr, int n) {
    if (n <= 1) {
        return;
    }
    insertionSortRecursive(arr, n - 1);
    int key = arr[n - 1];
    int j = n - 2;
    while (j >= 0 && arr[j] > key) {
        arr[j + 1] = arr[j];
        j--;
    }
    arr[j + 1] = key;
}
